using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Diagnostics;using RoomReservation.Domain.Entities;
namespace RoomReservation.Infrastructure.Persistence;public sealed class TenantSaveChangesInterceptor:SaveChangesInterceptor{public override InterceptionResult<int> SavingChanges(DbContextEventData e,InterceptionResult<int> result){Apply(e.Context);return base.SavingChanges(e,result);}public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData e,InterceptionResult<int> result,CancellationToken token=default){Apply(e.Context);return base.SavingChangesAsync(e,result,token);}static void Apply(DbContext? db){var org=TenantContext.OrganizationId;if(!org.HasValue||db is null)return;foreach(var entry in db.ChangeTracker.Entries().Where(x=>x.State==EntityState.Added)){if(entry.Entity is RoomAccess)continue;var p=entry.Metadata.FindProperty("OrganizationId");if(p is not null&&p.ClrType==typeof(Guid))entry.Property("OrganizationId").CurrentValue=org.Value;}}}
